import {tradingFixture} from './tradingFixture.mjs';import {createB2bPortalService,B2bError}from'../../server/b2b/portalService.mjs';import {createRegistrationService}from'../../server/b2b/registrationService.mjs';import {createCompanyDecisionNotifications}from'../../server/b2b/companyDecisionNotifications.mjs';import {currentLegalRegistry}from'../../server/b2b/legalAcceptance.mjs';
export async function integratedFixture(){
 const f=await tradingFixture({simple:true}),{h}=f;h.state.decisions=new Map();h.state.decisionCounter=0;const base=h.repository.transaction.bind(h.repository);let inTransaction=false;
 h.repository.transaction=work=>base(async tx=>{inTransaction=true;const decide=tx.decideCompany;try{return await work(Object.assign(tx,{
  companyDecisionRecipients:async companyId=>h.state.members.filter(m=>m.companyId===companyId).map(m=>{const u=h.state.users.get(m.userId),p=h.state.companies.get(companyId).profile;return {userId:u.id,email:u.email,language:h.state.preferences.get(u.id)?.language??p?.uiLanguage??'EN'}}),
  retirementMembers:async companyId=>h.state.members.filter(m=>m.companyId===companyId).map(m=>({userId:m.userId,email:h.state.users.get(m.userId).email,companyIds:h.state.members.filter(n=>n.userId===m.userId).map(n=>n.companyId)})),
  retireMember:async({userId,email,passwordHash,retiredEmail})=>{const u=h.state.users.get(userId);if(u.email!==email)throw Error('Email changed');u.email=retiredEmail;u.passwordHash=passwordHash;u.verifiedAt=null;for(const token of h.state.tokens)if(token.userId===userId&&!token.consumedAt)token.consumedAt=h.options.now();for(const [key,session]of h.state.sessions)if(session.userId===userId)h.state.sessions.delete(key);if(h.state.preferences.has(userId))h.state.preferences.get(userId).enabled=false;},
  decideCompany:async input=>{await decide(input);if(input.rejectedProfile){const c=h.state.companies.get(input.companyId);c.profile=structuredClone(input.rejectedProfile);c.number=null;}},
  enqueueCompanyDecision:async j=>{const old=[...h.state.decisions.values()].find(x=>x.companyId===j.companyId&&x.version===j.version&&x.userId===j.userId);if(old)return old.id;const id=++h.state.decisionCounter;h.state.decisions.set(id,{...structuredClone(j),id,status:'PENDING',attempt:0});return id;},
  pendingCompanyDecisions:async()=>[...h.state.decisions.values()].filter(j=>['PENDING','RETRY'].includes(j.status)&&(!j.next||j.next<=h.options.now())).map(j=>j.id),
  claimCompanyDecision:async id=>{const j=h.state.decisions.get(id);if(!j||!['PENDING','RETRY'].includes(j.status)||(j.next&&j.next>h.options.now())||j.attempt>=3)return null;const c=h.state.companies.get(j.companyId),u=h.state.users.get(j.userId);if(j.decision==='VERIFIED'&&(c.status!=='VERIFIED'||u.email!==j.email||c.profile.accessSuspended)){j.status='BLOCKED';return null}j.status='SENDING';j.attempt++;return structuredClone(j)},
  finishCompanyDecision:async(id,status)=>{const j=h.state.decisions.get(id);j.status=status;j.next=status==='RETRY'?h.options.now()+300000:null;}
 }))}finally{inTransaction=false}});
 const decisionEmails=[],decisionTransport={sendMail:async message=>{if(inTransaction)throw Error('MAIL_BEFORE_COMMIT');decisionEmails.push(message);return {accepted:[message.to],rejected:[]}}};const decisions=createCompanyDecisionNotifications({repository:h.repository,transport:decisionTransport,origin:'https://seedtrade.eu',from:'network@seedtrade.eu'});const adminToken='a'.repeat(64),adminId='b'.repeat(32);const admin=createB2bPortalService({...h.options,memberOnly:true,adminUserIds:[],decisionNotifications:decisions,reviewActor:async(tx,token)=>{if(token!==adminToken)throw new B2bError(401,'ADMIN_SIGN_IN_REQUIRED');return {adminId,platformAdmin:true,historicalRecordRestrictions:[1,2,3]}}});
 const registration=createRegistrationService({...h.options,simpleRegistration:true});const input=(email,number,language='EN')=>({email,uiLanguage:language,termsAccepted:true,locale:'en',legalBundleId:currentLegalRegistry.bundleId,company:{legalName:'Local integrated company '+number,registrationNumber:number,registrationCountry:'LT',registeredAddress:{street:'Test Street 1',city:'Vilnius',postalCode:'00000'},contactFirstName:'Local',contactLastName:'Representative'}});
 const register=async(email,number,language='EN')=>{const data=input(email,number,language),created=await registration.register(data),mail=h.mail.at(-1),password='local new member password '+number;await registration.verifyEmail({userId:created.userId,token:mail.token,password});return {...await f.service.login({email,password}),password,data}};
 return {...f,admin,adminToken,adminId,decisions,decisionEmails,decisionTransport,registration,input,register};
}
